#include <iostream>
using namespace std;

using lli = long long;

const lli MOD = 998244353;

lli modPow(lli base, lli exponent) {
    lli result = 1;
    base %= MOD;

    while (exponent > 0) {
        if (exponent & 1) {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exponent >>= 1;
    }

    return result;
}

int main() {
    lli x1, x2;
    cin >> x1 >> x2;

    cout << modPow(2, x1) * modPow(2, x2) % MOD;
    return 0;
}

